package com.microllm.tensor;
import java.util.*;
public final class Tensor { private final int[] shape; private final double[] values,gradient; public Tensor(int...s){this(new double[size(s)],s);} public Tensor(double[]v,int...s){if(v.length!=size(s))throw new IllegalArgumentException("shape");shape=s.clone();values=v.clone();gradient=new double[v.length];} public static Tensor zeros(int...s){return new Tensor(s);} public static Tensor ones(int...s){Tensor t=new Tensor(s);Arrays.fill(t.values,1);return t;} public static Tensor randomNormal(Random r,double d,int...s){Tensor t=new Tensor(s);for(int i=0;i<t.size();i++)t.values[i]=r.nextGaussian()*d;return t;} public int size(){return values.length;} public double get(int i){return values[i];} public void set(int i,double v){values[i]=v;} public double[] values(){return values;} public double[] gradient(){return gradient;} public void zeroGradient(){Arrays.fill(gradient,0);} private static int size(int[]s){int n=1;for(int x:s){if(x<1)throw new IllegalArgumentException("shape");n*=x;}return n;} }
